const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define locations
  const airport = ee.Geometry.Point([85.8170, 20.2543]); // Biju Patnaik Airport coordinates
  const saheedNagar = ee.Geometry.Point([85.848691, 20.290813]); // Given coordinates

  // Define date range
  const startDate = '2019-04-30';
  const endDate = '2019-05-05';

  // Get VIIRS nighttime lights collection
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filterDate(startDate, endDate);

  // Check collection size
  const count = viirs.size().getInfo();
  console.log(`VIIRS images found: ${count}`);

  if (count === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get images for start and end dates
  const startImg = viirs.filterDate('2019-04-30', '2019-05-01').first();
  const endImg = viirs.filterDate('2019-05-04', '2019-05-06').first();

  if (!startImg || !endImg) {
    console.log("Missing start or end date images");
    console.log("<answer>C1</answer>");
    return;
  }

  // Extract brightness values using avg_rad band
  const airportStart = startImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: airport,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const airportEnd = endImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: airport,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const saheedStart = startImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: saheedNagar,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const saheedEnd = endImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: saheedNagar,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log(`Airport: ${airportStart?.toFixed(3)} -> ${airportEnd?.toFixed(3)}`);
  console.log(`Saheed: ${saheedStart?.toFixed(3)} -> ${saheedEnd?.toFixed(3)}`);

  // Check for null values
  if (airportStart === null || airportEnd === null || saheedStart === null || saheedEnd === null) {
    console.log("Null values detected");
    console.log("<answer>C3</answer>");
    return;
  }

  // Calculate changes (decrease = negative change)
  const airportChange = airportEnd - airportStart;
  const saheedChange = saheedEnd - saheedStart;

  console.log(`Airport change: ${airportChange.toFixed(3)}`);
  console.log(`Saheed change: ${saheedChange.toFixed(3)}`);

  // Check if airport decreased more than saheed (more negative)
  if (airportChange < saheedChange) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
